class Solution {
public:
    int minimumLength(string s) {
        vector<int> freq(26, 0);
        for (char c : s) {
            freq[c - 'a']++;
        }
        int total = 0;
        for (int c : freq) {
            if (c > 0) {
                total += (c % 2 == 1) ? 1 : 2;
            }
        }
        return total;
    }
};

class Solution {
    public int minimumLength(String s) {
        int[] freq = new int[26];
        for (char c : s.toCharArray()) {
            freq[c - 'a']++;
        }
        int total = 0;
        for (int c : freq) {
            if (c > 0) {
                total += (c % 2 == 1) ? 1 : 2;
            }
        }
        return total;
    }
}

var minimumLength = function(s) {
    const freq = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        freq[s.charCodeAt(i) - 97]++;
    }
    let total = 0;
    for (const c of freq) {
        if (c > 0) {
            total += (c % 2 === 1) ? 1 : 2;
        }
    }
    return total;
};
